/* ---------- LE GRAND LAC (asset du propriétaire) ----------
   Zone fixe de plusieurs cases, toujours au même endroit : côté droit du
   plateau, en haut vers la diagonale. Aucun objet ni décor ne s'y pose. */
const LAC = { ok: false, mips: {}, hw: 0.690, w: 2.0 };
(function () {
  const img = new Image();
  img.onload = () => { LAC.img = img; LAC.ok = true; };
  img.src = "data:image/webp;base64,";
})();
const LAC_CELLS = [[5, 1], [6, 1], [7, 1], [5, 2], [6, 2], [7, 2], [6, 3], [7, 3]];
const lacSet = new Set(LAC_CELLS.map((c) => c[0] + "," + c[1]));
const LAC_CX = LAC_CELLS.reduce((a, c) => a + c[0], 0) / LAC_CELLS.length;
const LAC_CY = LAC_CELLS.reduce((a, c) => a + c[1], 0) / LAC_CELLS.length;
function lacImg() {
  const px = LAC.w * TILE.world * cam.z * DPR;
  const w = [256, 512, LAC.img.width].find((v) => v >= px) || LAC.img.width;
  let c = LAC.mips[w];
  if (!c) {
    c = LAC.mips[w] = document.createElement("canvas");
    c.width = w; c.height = Math.round(w * LAC.img.height / LAC.img.width);
    c.getContext("2d").drawImage(LAC.img, 0, 0, c.width, c.height);
  }
  return c;
}
